describe('File Upload with Title and Description', () => {
    beforeEach(() => {
        cy.visit('/file-upload'); // Adjust the URL to your application's file upload page
    });

    it('should successfully upload a file with a title and description', () => {
        const fileName = 'example.pdf'; // Ensure this file exists in the fixtures
        const title = 'Test File';
        const description = 'This is a test file for upload.';

        cy.get('input[type="file"]').attachFile(fileName);
        cy.get('input[name="title"]').type(title);
        cy.get('textarea[name="description"]').type(description);
        cy.get('button[type="submit"]').click();

        cy.get('.success-message').should('contain', 'File uploaded successfully');
        cy.get('.uploaded-file-title').should('contain', title);
        cy.get('.uploaded-file-description').should('contain', description);
    });

    it('should show an error when title is missing', () => {
        const fileName = 'example.pdf'; // Ensure this file exists in the fixtures
        const description = 'This is a test file for upload without a title.';

        cy.get('input[type="file"]').attachFile(fileName);
        cy.get('textarea[name="description"]').type(description);
        cy.get('button[type="submit"]').click();

        cy.get('.error-message').should('contain', 'Title is required');
    });
});
